  "importExport.sdbh.notImported.body": {"forms":{"one":"{count}টি প্রাসঙ্গিক অর্থ {max}-এর বেশি পদ রেফারেন্স তালিকা করে। তার রেফারেন্স তালিকা সেলে রাখার জন্য বড়, তাই সেই ঘরের জন্য সেল “আমদানি হয়নি” চিহ্নিত হবে।","other":"{count}টি প্রাসঙ্গিক অর্থ {max}-এর বেশি পদ রেফারেন্স তালিকা করে। তাদের রেফারেন্স তালিকা সেলে রাখার জন্য বড়, তাই সেই ঘরের জন্য সেই সেলগুলো “আমদানি হয়নি” চিহ্নিত হবে।"},"countVar":"count"},
  "importExport.sdbh.notImported.exportNote": "লেক্সিকনের লেখা নিজে পুরো আমদানি হয়। রপ্তানি সংরক্ষিত সংস্করণ ফাইল থেকে আবার বানায়, তাই আসল রেফারেন্স ডেটা অপরিবর্তিত।",
