  "projectSettings.sourceLink.chooseFilesKeepOneError": "অন্তত একটি ফাইল লিংক থাকতে হবে। উৎস প্রকল্প একেবারে অনুসরণ বন্ধ করতে “উৎস থেকে বিচ্ছিন্ন করুন” ব্যবহার করুন।",
  "projectSettings.sourceLink.chooseFilesResumeHeading": {"forms":{"one":"এই ফাইল আবার অনুসরণ করুন:","other":"এই ফাইলগুলো আবার অনুসরণ করুন:"},"countVar":"count"},
