  "workspace.update.refusedToast": {"forms":{"one":"Aquilla {version} প্রস্তুত, কিন্তু {count}টি পরিবর্তন সার্ভারে পৌঁছায়নি — প্রত্যাখ্যাত, তাই নিজে পাঠাবে না। এখন হালনাগাদ করলে এটি এই ডিভাইসে সংরক্ষিত থাকে।","other":"Aquilla {version} প্রস্তুত, কিন্তু {count}টি পরিবর্তন সার্ভারে পৌঁছায়নি, এবং কিছু প্রত্যাখ্যাত তাই নিজে পাঠাবে না। এখন হালনাগাদ করলে সব এই ডিভাইসে সংরক্ষিত থাকে।"},"countVar":"count"},
